/**
 * The app's sensor decoding and levelling must match the ESP32 app. The
 * expected values come from shared/fixtures/, generated by running the ESP32
 * code (esp32/tools/make_fixtures.py).
 */

import { describe, expect, test } from '@jest/globals';
import levelling from '../../shared/fixtures/levelling.json';
import sensor from '../../shared/fixtures/sensor.json';
import {
  DISPLAY_PITCH_SENSOR_KEY,
  DISPLAY_PITCH_SIGN,
  DISPLAY_ROLL_SENSOR_KEY,
  DISPLAY_ROLL_SIGN,
  SENSOR_POWER_READ_COMMAND,
} from '../src/config';
import { cornerLifts, isLevel, vanTilt, vehicleAttitude, wedgeAdvice } from '../src/levelling';
import { batteryPercent, decodePacket, decodePowerResponse, hexToBytes, splitFrames } from '../src/sensor/protocol';

const dims = {
  wheelbaseMm: levelling.vehicle.wheelbase_mm,
  frontTrackMm: levelling.vehicle.front_track_mm,
  rearTrackMm: levelling.vehicle.rear_track_mm,
};

describe('sensor packets', () => {
  test.each(sensor.attitude_packets)('decodes $hex', ({ hex, decoded }) => {
    const result = decodePacket(hexToBytes(hex));
    if (decoded === null) {
      expect(result).toBeNull();
      return;
    }
    expect(result).not.toBeNull();
    for (const [key, value] of Object.entries(decoded)) {
      expect(result![key as keyof typeof result]).toBeCloseTo(value as number, 5);
    }
  });

  test('power read command', () => {
    expect(SENSOR_POWER_READ_COMMAND).toEqual(hexToBytes(sensor.power_read_command));
  });

  test("power response from the owner's sensor", () => {
    const power = decodePowerResponse(hexToBytes(sensor.power_response.hex));
    expect(power).toEqual({ raw: 385, voltage: 3.85, percent: sensor.power_response.percent });
  });

  test.each(sensor.notifications)('splits a notification of $hex', ({ hex, frames }) => {
    expect(splitFrames(hexToBytes(hex))).toEqual(frames.map(hexToBytes));
  });

  test.each(sensor.battery_percent)('battery raw %d is %d %%', (raw, percent) => {
    expect(batteryPercent(raw)).toBe(percent);
  });
});

describe('levelling', () => {
  test('axis mapping matches the ESP32 config', () => {
    expect(levelling.axis_mapping).toEqual({
      pitch_from: DISPLAY_PITCH_SENSOR_KEY,
      pitch_sign: DISPLAY_PITCH_SIGN,
      roll_from: DISPLAY_ROLL_SENSOR_KEY,
      roll_sign: DISPLAY_ROLL_SIGN,
    });
  });

  test.each(levelling.cases)('sensor $sensor with zero $zero', (c) => {
    const attitude = vehicleAttitude(c.sensor, c.zero);
    expect(attitude.pitch).toBeCloseTo(c.vehicle.pitch, 5);
    expect(attitude.roll).toBeCloseTo(c.vehicle.roll, 5);

    const lifts = cornerLifts(attitude, dims);
    for (const [corner, value] of Object.entries(c.lift_cm)) {
      expect(lifts[corner as keyof typeof lifts]).toBeCloseTo(value, 5);
    }
    expect(wedgeAdvice(lifts)).toEqual(c.wedges === 'LEVEL' ? 'level' : c.wedges);
    expect(vanTilt(attitude.roll)).toBeCloseTo(c.van_tilt.rear, 5);
    expect(-vanTilt(attitude.pitch)).toBeCloseTo(c.van_tilt.side, 5);
  });

  test.each(levelling.level_hysteresis)(
    'pitch %d roll %d was level %s -> %s',
    (pitch, roll, wasLevel, expected) => {
      expect(isLevel(pitch as number, roll as number, wasLevel as boolean)).toBe(expected);
    },
  );
});
